import type { AuthSession } from "@jcoder-stack/abp-react/auth";
import { HUB_NAME_PATTERN, type HubConnectionInfo } from "@jcoder-stack/abp-react/realtime";
import { z } from "zod";

export const hubInputSchema = z.object({ hub: z.string().regex(HUB_NAME_PATTERN) });

/** ABP maps hubs under this path unless the backend sets AbpSignalROptions otherwise. */
export const DEFAULT_HUB_PREFIX = "/signalr-hubs";

/**
 * Derives what the browser needs to open `hub`. The URL is built here, on the server, from the
 * backend origin the BFF already trusts, so the client never names an arbitrary host.
 */
export function hubConnectionInfo(opts: {
  session: AuthSession | null;
  abpBaseUrl: string;
  hubPrefix: string | undefined;
  hub: string;
}): HubConnectionInfo | null {
  if (opts.session === null) return null;
  const trimmed = opts.hubPrefix?.trim().replace(/^\/+|\/+$/g, "") ?? "";
  const prefix = trimmed === "" ? DEFAULT_HUB_PREFIX : `/${trimmed}`;
  return {
    url: `${opts.abpBaseUrl.replace(/\/+$/, "")}${prefix}/${opts.hub}`,
    accessToken: opts.session.tokens.accessToken,
    expiresAt: opts.session.expiresAt ?? null,
  };
}

import { createServerFn } from "@tanstack/react-start";
import { authMiddleware } from "@/auth/middleware";
import { getAuthRuntime } from "@/auth/runtime";
import { hubConnectionInfo, hubInputSchema } from "@/features/signalr/hub-connection-info";

/**
 * Hands the signed-in browser a short-lived token for one SignalR hub: the single, bounded
 * exception to "tokens never reach the browser" (docs/architecture.md). authMiddleware refreshes
 * an expiring session first, so the token handed out is always fresh. Anonymous visitors get null.
 */
export const getHubConnectionInfoFn = createServerFn({ method: "GET" })
  .validator(hubInputSchema)
  .middleware([authMiddleware])
  .handler(({ data, context }) =>
    hubConnectionInfo({
      session: context.session,
      abpBaseUrl: getAuthRuntime().env.abpBaseUrl,
      // 不进应用的 src/env.ts：那个文件归应用所有，功能安装不改它。
      hubPrefix: process.env.SIGNALR_HUB_PREFIX,
      hub: data.hub,
    }),
  );

import { RealtimeProvider } from "@jcoder-stack/abp-react/realtime";
import type { ReactNode } from "react";
import type { FeatureModule } from "@/features/compose";
import { getHubConnectionInfoFn } from "@/features/signalr/server-fns";

/** Module level: RealtimeProvider reads it once and needs one stable reference. */
const getConnectionInfo = (hub: string) => getHubConnectionInfoFn({ data: { hub } });

function SignalRProvider({ children }: { children: ReactNode }) {
  return <RealtimeProvider getConnectionInfo={getConnectionInfo}>{children}</RealtimeProvider>;
}

const signalr: FeatureModule = { Provider: SignalRProvider };

export default signalr;
